<div class="monthly-report-brand"><span class="arpico-logo-window"><img src="<?=e(app_url('assets/arpico-logo.jpg'))?>" alt="ARPICO" width="1200" height="630"></span><strong>Attendance report</strong></div>
<div class="monthly-identity"><h2><?=e($person['name'])?></h2><p class="summary-date-caption">Summary period: <strong><?=e($start)?> → <?=e($end)?></strong></p><p>Employee ID: <strong><?=e($person['employee_code'])?></strong><small><?=e($person['department'])?></small></p></div>
<button type="button" class="secondary monthly-print-button" data-attendance-print="month">Print monthly summary / PDF</button><div class="monthly-overview"><div class="stats"><div><span>Recorded workdays</span><strong><?=count($daily)?></strong></div><div><span>Completed net hours · HH:MM</span><strong><?=e(hours(array_sum(array_column($daily,'net'))))?></strong></div><div><span>Late minutes</span><strong><?=array_sum(array_column($daily,'late'))?></strong></div><div><span>Open workdays</span><strong><?=$openCount?></strong></div></div>
<div class="monthly-ot-status"><span>OT totals</span><?php if($openCount):?><span class="badge amber" title="Open workdays are excluded from the OT totals until checkout or approved correction.">Pending · <?=$openCount?> open workday(s)</span><?php endif;?></div><div class="ot-breakdown"><?php foreach(['weekday_ot'=>'Weekday OT','single_ot'=>'Weekend OT · First 8h','double_ot'=>'Weekend OT · After 8h'] as $key=>$label):?><div class="ot-summary"><span><?=e($label)?> · HH:MM</span><strong><?=e(hours(array_sum(array_column($daily,$key))))?></strong></div><?php endforeach;?></div>
<div class="stats compact"><div><span>Scheduled days</span><strong><?=count(array_filter($calendar,fn($c)=>$c['working']))?></strong></div><div><span>Approved leave days</span><strong><?=array_sum(array_map(fn($c)=>$c['working']?$c['leave_units']:0,$calendar))?></strong></div><div><span>Holidays</span><strong><?=count(array_filter($calendar,fn($c)=>$c['holiday']!==''))?></strong></div><div><span>Past days needing entry review</span><strong><?=array_sum(array_column($calendar,'missing_units'))?></strong></div></div>
</div><div class="monthly-details"><h3>Daily details</h3><p class="muted hours-format-note">Hours use HH:MM: 08:30 means 8 hours 30 minutes.</p><form class="filters" method="get"><input type="hidden" name="month" value="<?=e($summaryMonth)?>"><label>From<input type="date" name="summary_from" value="<?=e($summarySelected?$from:'')?>" required></label><label>To<input type="date" name="summary_to" value="<?=e($summarySelected?$to:'')?>" required></label><input type="hidden" name="employee" value="<?=e($employee)?>"><button>Apply</button><button name="export" value="csv" class="secondary">Export CSV</button><button type="button" class="secondary" data-attendance-print="daily" <?=$summarySelected?'':'disabled'?>>Print daily details / PDF</button><?php if($summarySelected):?><a href="<?=e(app_url('monthly').'?'.http_build_query(['month'=>$summaryMonth,'employee'=>$employee]))?>">Reset</a><?php endif;?></form><?php if($summarySelected):?><p class="daily-date-caption">Daily details range: <strong><?=e($from)?> → <?=e($to)?></strong></p><div class="table-wrap my-records-table monthly-daily-table"><table><thead><tr><th>Date</th><th>Check in</th><th>Check out</th><th>Net hours<small>HH:MM</small></th><th>Late min</th><th>Weekday OT<small>HH:MM</small></th><th>Weekend OT · First 8h<small>HH:MM</small></th><th>Weekend OT · After 8h<small>HH:MM</small></th><th>Status / leave</th></tr></thead><tbody>
<?php foreach($ordered as $i=>$c):$d=$c['day'];$sessions=$sessionByDate[$c['date']]??[];?><tr class="<?=$d&&$d['open']?'daily-row-open ':''?><?=$d&&$d['late']>0?'daily-row-late':''?>"><td><strong><?=e($c['date'])?></strong><?php if(count($sessions)>1):?><small><?=count($sessions)?> sessions</small><?php endif;?></td><td><?=$d?e(local_time($d['first'],'d M, H:i')):'—'?></td><td><?=$d&&$d['last']?e(local_time($d['last'],'d M, H:i')):($d&&$d['open']?'Pending checkout':'—')?><?php if($d&&$d['open']&&$d['last']):?><small>Last completed checkout</small><?php endif;?><?php if($d&&$d['last']&&local_time($d['last'],'Y-m-d')>$c['date']):?><small class="overnight-checkout">Checkout on <?=e(local_time($d['last'],'Y-m-d'))?></small><?php endif;?></td><td><?=$d?e(hours($d['net'])):'—'?><?php if($d&&$d['open']):?><small>Completed sessions only</small><?php endif;?></td><td><?php if($d&&$d['late']>0):?><span class="badge late-badge"><?=e($d['late'])?></span><?php else:?><?=$d?'0':'—'?><?php endif;?></td><?php foreach(['weekday_ot','single_ot','double_ot'] as $key):?><td><?=$d&&$d[$key]!==null?e(hours($d[$key])):'—'?></td><?php endforeach;?><td><span class="badge <?=$d&&$d['open']?'amber':($d&&$d['late']>0?'late-badge':'neutral')?>"><?=e($c['status'].($d&&!$d['open']&&$d['late']>0?' · Late':''))?></span><?php if($d&&$d['open']):?><small>OT pending</small><?php endif;?><?php foreach($pendingCorrections[$c['date']]??[] as $pending):?><small class="pending-correction">Pending correction #<?=e($pending['id'])?></small><?php endforeach;?><?php if($c['holiday']!==''):?><small><?=e($c['holiday'])?></small><?php endif;?><?php foreach($c['leaves'] as $leave):?><small><?=e(ucfirst($leave['leave_type']).' · '.leave_part_label($leave['leave_part']))?></small><?php endforeach;?></td></tr><?php endforeach;?><?php if(!$ordered):?><tr><td colspan="9" class="empty">No dates found in the selected range.</td></tr><?php endif;?></tbody></table></div>
<?php else:?><p class="empty">Select a From / To range above and click Apply to view daily details.</p><?php endif;?></div></section>
